// Validate catalog structure immediately on module load
const validationReport = validateCurriculumCatalog(CURRICULUM_CATALOG);
if (!validationReport.valid) {
  console.error('[CurriculumCatalog] Validation errors:', validationReport.errors);
}

/**
 * Returns public CEFR level structures with sanitized units and lesson nodes (no answer keys).
 */
export function getPublicLevels() {
  return CURRICULUM_CATALOG.levels.map(level => ({
    id: level.id,
    code: level.code,
    name: level.name,
    badge: level.badge,
    tagline: level.tagline,
    objective: level.objective,
    accentColor: level.accentColor,
    estimatedHours: level.estimatedHours,
    sections: level.sections.map(section => ({
      id: section.id,
      sectionNumber: section.sectionNumber,
      title: section.title,
      tagline: section.tagline,
      description: section.description,
      units: section.units.map(unit => ({
        id: unit.id,
        unitNumber: unit.unitNumber,
        title: unit.title,
        eyebrow: unit.eyebrow,
        objective: unit.objective,
        lessons: unit.lessons.map(lesson => ({
          id: lesson.id,
          title: lesson.title,
          subtitle: lesson.subtitle,
          lessonType: lesson.lessonType,
          pedagogicalFocus: lesson.pedagogicalFocus,
          icon: lesson.icon,
          accentColor: lesson.accentColor,
          xp: lesson.xp,
          estimatedDurationMin: lesson.estimatedDurationMin,
          description: lesson.description,
          prerequisites: lesson.prerequisites,
          objectives: lesson.objectives,
          exerciseCount: lesson.exercises?.length || 0
        }))
      }))
    }))
  }));
}

/**
 * Finds and returns a public lesson with sanitized exercises (strictly omitting solution keys).
 */
export function getPublicLesson(lessonId) {
  for (const level of CURRICULUM_CATALOG.levels) {
    for (const section of level.sections) {
      for (const unit of section.units) {
        for (const lesson of unit.lessons) {
          if (lesson.id === lessonId) {
            return {
              id: lesson.id,
              levelId: level.id,
              levelCode: level.code,
              levelName: level.name,
              sectionId: section.id,
              unitId: unit.id,
              unitTitle: unit.title,
              title: lesson.title,
              subtitle: lesson.subtitle,
              lessonType: lesson.lessonType,
              pedagogicalFocus: lesson.pedagogicalFocus,
              icon: lesson.icon,
              accentColor: lesson.accentColor,
              xp: lesson.xp,
              estimatedDurationMin: lesson.estimatedDurationMin,
              description: lesson.description,
              prerequisites: lesson.prerequisites,
              objectives: lesson.objectives || [],
              learningObjectives: (lesson.objectives || []).map(id => CURRICULUM_CATALOG.learningObjectives?.[id]).filter(Boolean),
              primaryObjective: CURRICULUM_CATALOG.learningObjectives?.[lesson.objectives?.[0]] || null,
              vocabulary: lesson.vocabulary || [],
              grammar: lesson.grammar || null,
              explanation: lesson.explanation || null,
              workedExamples: lesson.workedExamples || [],
              guidedPractice: lesson.guidedPractice || null,
              independentPractice: lesson.independentPractice || null,
              review: lesson.review || null,
              exercises: (lesson.exercises || []).map(ex => ({
                id: ex.id,
                exerciseType: ex.exerciseType,
                prompt: ex.prompt,
                options: ex.options,
                explanation: ex.explanation,
                ...(ex.audioUrl ? { audioUrl: ex.audioUrl } : {}),
                ...(ex.passage ? { passage: ex.passage } : {}),
                ...(ex.targetPhrase ? { targetPhrase: ex.targetPhrase } : {}),
                ...(ex.referenceAudioUrl ? { referenceAudioUrl: ex.referenceAudioUrl } : {}),
                ...(ex.phonetic ? { phonetic: ex.phonetic } : {})
                // solutionKey and correctIndex are strictly omitted from public output
              }))
            };
          }
        }
      }
    }
  }
  return null;
}

/**
 * Returns secret solution keys for server-side grading.
 * Strictly internal to server.mjs.
 */
export function getLessonSolutionKeys(lessonId) {
  for (const level of CURRICULUM_CATALOG.levels) {
    for (const section of level.sections) {
      for (const unit of section.units) {
        for (const lesson of unit.lessons) {
          if (lesson.id === lessonId) {
            return (lesson.exercises || []).map(ex => ({
              id: ex.id,
              solutionKey: ex.solutionKey
            }));
          }
        }
      }
    }
  }
  return null;
}

/**
 * Retrieves authoritative canonical lesson by ID.
 */
export function getLessonById(lessonId) {
  for (const level of CURRICULUM_CATALOG.levels) {
    for (const section of level.sections) {
      for (const unit of section.units) {
        for (const lesson of unit.lessons) {
          if (lesson.id === lessonId) {
            return lesson;
          }
        }
      }
    }
  }
  return null;
}

/**
 * Checks whether all prerequisite lessons for a given lesson are fulfilled.
 */
export function checkLessonPrerequisites(lessonId, completed = []) {
  const lesson = getLessonById(lessonId);
  if (!lesson) {
    return { found: false, unlocked: false, missing: [] };
  }
  const prereqs = Array.isArray(lesson.prerequisites) ? lesson.prerequisites : [];
  if (prereqs.length === 0) {
    return { found: true, unlocked: true, missing: [], lesson };
  }
  const completedSet = new Set(Array.isArray(completed) ? completed : []);
  const missing = prereqs.filter(p => !completedSet.has(p));
  return {
    found: true,
    unlocked: missing.length === 0,
    missing,
    lesson
  };
}

